    "utf8_text": "//! The existing i64 DAG-CBOR profile. Storage moves bytes without re-encoding.
use sha2::{Digest, Sha256};
use std::collections::BTreeMap;

pub type Result<T> = std::result::Result<T, String>;
pub const MAX_BYTES: usize = 4 * 1024 * 1024;
pub const MAX_BLOCKS: usize = 256;
pub const MAX_PACKET: usize = MAX_BYTES + MAX_BLOCKS * 40 + 16;
const PREFIX: [u8; 4] = [1, 0x71, 0x12, 0x20];

#[derive(Clone, Debug, PartialEq)]
pub enum Value {
    Null,
    Bool(bool),
    Int(i64),
    Bytes(Vec<u8>),
    Text(String),
    List(Vec<Value>),
    Map(BTreeMap<String, Value>),
    Link([u8; 36]),
}
impl Value {
    pub fn field(&self, key: &str) -> Result<&Value> {
        if let Self::Map(m) = self {
            m.get(key).ok_or_else(|| format!("missing field: {key}"))
        } else {
            Err("expected map".into())
        }
    }
    pub fn text(&self) -> Result<&str> {
        if let Self::Text(s) = self {
            Ok(s)
        } else {
            Err("expected text".into())
        }
    }
    pub fn link(&self) -> Result<[u8; 36]> {
        if let Self::Link(c) = self {
            Ok(*c)
        } else {
            Err("expected CID link".into())
        }
    }
    pub fn int(&self) -> Result<i64> {
        if let Self::Int(n) = self {
            Ok(*n)
        } else {
            Err("expected i64".into())
        }
    }
}

pub fn cid(data: &[u8]) -> [u8; 36] {
    let mut raw = [0; 36];
    raw[..4].copy_from_slice(&PREFIX);
    raw[4..].copy_from_slice(&Sha256::digest(data));
    raw
}
pub fn cid_text(raw: &[u8; 36]) -> String {
    let abc = b"abcdefghijklmnopqrstuvwxyz234567";
    let (mut bits, mut n) = (0u32, 0u32);
    let mut s = String::from("b");
    for byte in raw {
        bits = (bits << 8) | *byte as u32;
        n += 8;
        while n >= 5 {
            n -= 5;
            s.push(abc[((bits >> n) & 31) as usize] as char);
        }
    }
    if n > 0 {
        s.push(abc[((bits << (5 - n)) & 31) as usize] as char);
    }
    s
}
pub fn parse_cid(s: &str) -> Result<[u8; 36]> {
    if s.len() != 59 || !s.starts_with('b') {
        return Err("expected canonical CID".into());
    }
    let (mut bits, mut n) = (0u32, 0u32);
    let mut bytes = Vec::new();
    for ch in s.bytes().skip(1) {
        let v = match ch {
            b'a'..=b'z' => ch - b'a',
            b'2'..=b'7' => ch - b'2' + 26,
            _ => return Err("expected base32lower CID".into()),
        };
        bits = (bits << 5) | v as u32;
        n += 5;
        if n >= 8 {
            n -= 8;
            bytes.push(((bits >> n) & 255) as u8);
        }
    }
    let raw: [u8; 36] = bytes.try_into().map_err(|_| "CID width")?;
    if raw[..4] != PREFIX || cid_text(&raw) != s {
        return Err("noncanonical CID".into());
    }
    Ok(raw)
}

struct Reader<'a> {
    data: &'a [u8],
    pos: usize,
}
impl<'a> Reader<'a> {
    fn take(&mut self, n: usize) -> Result<&'a [u8]> {
        if n > self.data.len() - self.pos {
            return Err("truncated CBOR".into());
        }
        let p = self.pos;
        self.pos += n;
        Ok(&self.data[p..self.pos])
    }
    fn value(&mut self, depth: usize) -> Result<Value> {
        if depth > 64 {
            return Err("nesting limit exceeded".into());
        }
        let initial = self.take(1)?[0];
        let major = initial >> 5;
        let extra = initial & 31;
        if major == 7 {
            return match extra {
                20 => Ok(Value::Bool(false)),
                21 => Ok(Value::Bool(true)),
                22 => Ok(Value::Null),
                _ => Err("unsupported simple value or float".into()),
            };
        }
        let n = match extra {
            0..=23 => extra as u64,
            24..=27 => {
                let width = 1usize << (extra - 24);
                let mut n = 0;
                for byte in self.take(width)? {
                    n = (n << 8) | *byte as u64;
                }
                if n < [24, 256, 65536, 4294967296][(extra - 24) as usize] {
                    return Err("noncanonical integer or length".into());
                }
                n
            }
            _ => return Err("indefinite or reserved CBOR".into()),
        };
        match major {
            0 | 1 => {
                if n > i64::MAX as u64 {
                    return Err("integer outside i64 profile".into());
                }
                Ok(Value::Int(if major == 0 {
                    n as i64
                } else {
                    -1 - n as i64
                }))
            }
            2 | 3 => {
                let n = usize::try_from(n).map_err(|_| "length overflow")?;
                let raw = self.take(n)?;
                if major == 2 {
                    Ok(Value::Bytes(raw.to_vec()))
                } else {
                    Ok(Value::Text(
                        std::str::from_utf8(raw)
                            .map_err(|_| "invalid UTF-8")?
                            .into(),
                    ))
                }
            }
            4 | 5 => {
                if n > (self.data.len() - self.pos) as u64 {
                    return Err("impossible container length".into());
                }
                if major == 4 {
                    let mut out = Vec::new();
                    for _ in 0..n {
                        out.push(self.value(depth + 1)?);
                    }
                    Ok(Value::List(out))
                } else {
                    let mut out = BTreeMap::new();
                    let mut previous: Option<Vec<u8>> = None;
                    for _ in 0..n {
                        let start = self.pos;
                        let key = self.value(depth + 1)?;
                        let encoded = self.data[start..self.pos].to_vec();
                        let Value::Text(key) = key else {
                            return Err("non-string map key".into());
                        };
                        if previous.as_ref().is_some_and(|p| p >= &encoded) {
                            return Err("unordered or duplicate map key".into());
                        }
                        previous = Some(encoded);
                        out.insert(key, self.value(depth + 1)?);
                    }
                    Ok(Value::Map(out))
                }
            }
            6 if n == 42 => {
                let Value::Bytes(raw) = self.value(depth + 1)? else {
                    return Err("CID tag requires bytes".into());
                };
                if raw.len() != 37 || raw[0] != 0 || raw[1..5] != PREFIX {
                    return Err("unsupported CID profile".into());
                }
                Ok(Value::Link(raw[1..].try_into().map_err(|_| "CID width")?))
            }
            _ => Err("unsupported CBOR tag or major type".into()),
        }
    }
}
pub fn decode(data: &[u8]) -> Result<Value> {
    if data.len() > MAX_BYTES {
        return Err("block size limit exceeded".into());
    }
    let mut r = Reader { data, pos: 0 };
    let value = r.value(0)?;
    if r.pos != data.len() {
        return Err("trailing CBOR data".into());
    }
    Ok(value)
}
pub fn validate(raw: &[u8; 36], data: &[u8]) -> Result<Value> {
    if raw[..4] != PREFIX || cid(data) != *raw {
        return Err("block content does not match CID".into());
    }
    decode(data)
}

pub type Blocks = Vec<([u8; 36], Vec<u8>)>;
pub fn pack(blocks: &[([u8; 36], Vec<u8>)]) -> Result<Vec<u8>> {
    if blocks.len() > MAX_BLOCKS {
        return Err("batch block budget".into());
    }
    let mut out = b"MVM1".to_vec();
    out.extend((blocks.len() as u32).to_le_bytes());
    let mut total = 0;
    for (c, data) in blocks {
        total += data.len();
        if total > MAX_BYTES {
            return Err("batch byte budget".into());
        }
        out.extend(c);
        out.extend((data.len() as u32).to_le_bytes());
        out.extend(data);
    }
    Ok(out)
}
pub fn unpack(data: &[u8]) -> Result<Blocks> {
    let mut r = Reader { data, pos: 0 };
    if r.take(4)? != b"MVM1" {
        return Err("batch protocol version".into());
    }
    let count = u32::from_le_bytes(r.take(4)?.try_into().map_err(|_| "batch count")?) as usize;
    if count > MAX_BLOCKS {
        return Err("batch block budget".into());
    }
    let mut blocks = Vec::new();
    let mut total = 0;
    for _ in 0..count {
        let c = r.take(36)?.try_into().map_err(|_| "CID width")?;
        let n = u32::from_le_bytes(r.take(4)?.try_into().map_err(|_| "block length")?) as usize;
        total += n;
        if total > MAX_BYTES {
            return Err("batch byte budget".into());
        }
        let bytes = r.take(n)?.to_vec();
        validate(&c, &bytes)?;
        blocks.push((c, bytes));
    }
    if r.pos != data.len() {
        return Err("trailing batch data".into());
    }
    Ok(blocks)
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn strict_profile() {
        for bad in [
            vec![0x18, 0],
            vec![0x00, 0x00],
            vec![0x9f, 0xff],
            vec![0xfb; 9],
            vec![0xa2, 0x61, b'b', 0, 0x61, b'a', 0],
            vec![0xa2, 0x61, b'a', 0, 0x61, b'a', 0],
            vec![0x61, 0xff],
            vec![0x1b, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff],
        ] {
            assert!(decode(&bad).is_err(), "{bad:?}");
        }
        assert_eq!(
            decode(&[0x3b, 0x7f, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff]).unwrap(),
            Value::Int(i64::MIN)
        );
        let raw = cid(&[0xf6]);
        assert_eq!(parse_cid(&cid_text(&raw)).unwrap(), raw);
        assert!(parse_cid(&cid_text(&raw).to_uppercase()).is_err());
    }
    #[test]
    fn batch_identity_and_truncation() {
        let blocks = vec![(cid(&[0xf6]), vec![0xf6])];
        let data = pack(&blocks).unwrap();
        assert_eq!(unpack(&data).unwrap(), blocks);
        for i in 0..data.len() {
            assert!(unpack(&data[..i]).is_err());
        }
        let mut bad = data;
        bad.push(0);
        assert!(unpack(&bad).is_err());
    }
}
