use rusqlite::{params, Connection, OpenFlags, OptionalExtension, TransactionBehavior};
use std::{fs::OpenOptions, path::Path, time::Duration};

const APPLICATION_ID: i64 = 0x4d564d31;
fn sql<T>(value: rusqlite::Result<T>) -> Result<T> {
    value.map_err(|e| format!("SQLite: {e}"))
}

pub struct Store {
    pub connection: Connection,
}
impl Store {
    pub fn initialize(path: &Path) -> Result<()> {
        // Only an explicit new-store request creates storage. Failed initialization
        // remains visible; a later open never repairs or recreates it.
        OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(path)
            .map_err(|e| e.to_string())?;
        let c = sql(Connection::open(path))?;
        sql(c.execute_batch("PRAGMA journal_mode=WAL; PRAGMA synchronous=FULL;
            BEGIN IMMEDIATE;
            PRAGMA application_id=1297501489; PRAGMA user_version=1;
            CREATE TABLE blocks(cid BLOB PRIMARY KEY CHECK(length(cid)=36), data BLOB NOT NULL) WITHOUT ROWID;
            CREATE TABLE directory_entries(view BLOB NOT NULL, name_key BLOB NOT NULL,
                name TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL,
                extension TEXT NOT NULL, size INTEGER,
                PRIMARY KEY(view,name_key,name)) WITHOUT ROWID;
            CREATE TABLE directory_views(source BLOB PRIMARY KEY, result BLOB NOT NULL) WITHOUT ROWID;
            COMMIT;"))?;
        Ok(())
    }
    pub fn open(path: &Path, writable: bool) -> Result<Self> {
        let flags = if writable {
            OpenFlags::SQLITE_OPEN_READ_WRITE
        } else {
            OpenFlags::SQLITE_OPEN_READ_ONLY
        };
        let c = sql(Connection::open_with_flags(
            path,
            flags | OpenFlags::SQLITE_OPEN_NO_MUTEX,
        ))?;
        sql(c.busy_timeout(Duration::from_secs(2)))?;
        let id: i64 = sql(c.query_row("PRAGMA application_id", [], |r| r.get(0)))?;
        let version: i64 = sql(c.query_row("PRAGMA user_version", [], |r| r.get(0)))?;
        if id != APPLICATION_ID || version != 1 {
            return Err("unsupported native store schema".into());
        }
        if writable {
            sql(c.execute_batch("PRAGMA synchronous=FULL;"))?;
        } else {
            sql(c.execute_batch("PRAGMA query_only=ON;"))?;
        }
        Ok(Self { connection: c })
    }
    pub fn import(&mut self, blocks: &Blocks) -> Result<()> {
        codec::pack(blocks)?;
        // Validate the complete batch before a transaction or a first insertion.
        for (c, data) in blocks {
            codec::validate(c, data)?;
        }
        let tx = sql(self
            .connection
            .transaction_with_behavior(TransactionBehavior::Immediate))?;
        for (c, data) in blocks {
            let old: Option<Vec<u8>> = sql(tx
                .query_row(
                    "SELECT data FROM blocks WHERE cid=?1",
                    params![c.as_slice()],
                    |r| r.get(0),
                )
                .optional())?;
            if let Some(old) = old {
                if old != *data {
                    return Err("existing block differs; no overwrite or repair".into());
                }
            } else {
                sql(tx.execute(
                    "INSERT INTO blocks(cid,data) VALUES(?1,?2)",
                    params![c.as_slice(), data],
                ))?;
            }
        }
        sql(tx.commit())?;
        Ok(())
    }
    pub fn read(&self, c: &[u8; 36], limit: usize) -> Result<Vec<u8>> {
        if limit > MAX_BYTES {
            return Err("invalid block read budget".into());
        }
        // Check the SQL length before materializing the BLOB into host memory.
        let n: Option<i64> = sql(self
            .connection
            .query_row(
                "SELECT length(data) FROM blocks WHERE cid=?1",
                params![c.as_slice()],
                |r| r.get(0),
            )
            .optional())?;
        let n = n.ok_or_else(|| format!("missing block: {}", codec::cid_text(c)))?;
        if n < 0 || n as usize > limit {
            return Err(format!(
                "block exceeds read limit {limit}: {}",
                codec::cid_text(c)
            ));
        }
        let data: Vec<u8> = sql(self.connection.query_row(
            "SELECT data FROM blocks WHERE cid=?1",
            params![c.as_slice()],
            |r| r.get(0),
        ))?;
        if data.len() > limit {
            return Err("block changed during read".into());
        }
        codec::validate(c, &data)?;
        Ok(data)
    }
    pub fn read_batch(&mut self, keys: &[[u8; 36]], limit: usize) -> Result<Blocks> {
        if keys.len() > codec::MAX_BLOCKS || limit > MAX_BYTES {
            return Err("batch read budget".into());
        }
        // One consistent read view. Any missing/corrupt block rejects the batch.
        sql(self.connection.execute_batch("BEGIN;"))?;
        let result = (|| {
            let mut out = Vec::new();
            let mut total = 0;
            for key in keys {
                let bytes = self.read(key, limit)?;
                total += bytes.len();
                if total > MAX_BYTES {
                    return Err("batch byte budget".into());
                }
                out.push((*key, bytes));
            }
            Ok(out)
        })();
        let end = sql(self.connection.execute_batch("ROLLBACK;"));
        end?;
        result
    }
    pub fn publish_directory(&mut self, result: &[u8; 36]) -> Result<[u8; 36]> {
        // Called only after the trusted legacy bridge has discharged its check.
        // Projection publication confers no file-open or execution authority.
        let data = self.read(result, MAX_BYTES)?;
        let value = codec::decode(&data)?;
        let Value::Map(m) = &value else {
            return Err("directory result must be map".into());
        };
        if m.keys().map(String::as_str).collect::<Vec<_>>()
            != [
                "adoption",
                "entries",
                "goal",
                "manifest",
                "material",
                "observed_ns",
                "schema",
                "scope",
                "source",
            ]
            || value.field("schema")?.text()? != "mvm.directory-metadata-result.v1"
            || value.field("scope")?.text()?
                != "direct children; metadata only; non-atomic host observation"
            || value.field("adoption")?.text()? != "not-authorized"
        {
            return Err("unsupported directory result".into());
        }
        let source = value.field("source")?.link()?;
        for key in ["goal", "material", "manifest"] {
            let c = value.field(key)?.link()?;
            self.read(&c, MAX_BYTES)?;
        }
        self.read(&source, MAX_BYTES)?;
        value.field("observed_ns")?.int()?;
        let Value::List(entries) = value.field("entries")? else {
            return Err("directory entries must be list".into());
        };
        if entries.len() > 64 {
            return Err("legacy observation scope exceeded".into());
        }
        let mut rows = Vec::new();
        for e in entries {
            let name = e.field("name")?.text()?.to_owned();
            let size = match e.field("size")? {
                Value::Null => None,
                v => Some(v.int()?),
            };
            rows.push((
                name.to_lowercase().into_bytes(),
                name,
                e.field("kind")?.text()?.to_owned(),
                e.field("status")?.text()?.to_owned(),
                e.field("extension")?.text()?.to_owned(),
                size,
            ));
        }
        let tx = sql(self
            .connection
            .transaction_with_behavior(TransactionBehavior::Immediate))?;
        for (key, name, kind, status, extension, size) in rows {
            sql(tx.execute("INSERT OR IGNORE INTO directory_entries(view,name_key,name,kind,status,extension,size)
                VALUES(?1,?2,?3,?4,?5,?6,?7)",params![result.as_slice(),key,name,kind,status,extension,size]))?;
