ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from merkle_vm.codec import InvalidObject, cid_for, encode
from merkle_vm.native_store import NativeBlockStore

OUT = ROOT / 'reports/round-0212-error-exits'
EXE = ROOT / 'native/target/release/mvm-native.exe'
OUT.mkdir(exist_ok=False)
calls = []
started = datetime.now(timezone.utc).isoformat()

def call(label, *args, success=True):
    before = time.perf_counter_ns()
    p = subprocess.run([str(EXE), *map(str, args)], capture_output=True, timeout=90, cwd=ROOT)
    (OUT / (label + '-stdout.bin')).write_bytes(p.stdout)
    (OUT / (label + '-stderr.bin')).write_bytes(p.stderr)
    calls.append(dict(label=label, command=[str(EXE), *map(str, args)], returncode=p.returncode,
                      elapsed_ns=time.perf_counter_ns()-before))
    assert (p.returncode == 0) is success, (label, p.returncode, p.stderr)
    return json.loads(p.stdout) if success else p

def sql(database, statement, parameters=()):
    with closing(sqlite3.connect(database)) as c:
        rows = c.execute(statement, parameters).fetchall()
        c.commit()
        return rows

class CaptureStore(NativeBlockStore):
    def __init__(self, *args, **kwargs):
        self.raw_output = bytearray()
        self.raw_input = bytearray()
        super().__init__(*args, **kwargs)
    def _exact(self, size):
        raw = super()._exact(size)
        self.raw_output.extend(raw)
        return raw
    def _request(self, raw):
        self.raw_input.extend(struct.pack('<I', len(raw)) + raw)
        return super()._request(raw)

# A real SQL statement fails after a prior insertion in the same transaction.
# Recover on this exact worker, then verify retained identities on another read.
database = OUT / 'statement-failure.sqlite'
call('statement-init', 'init', database)
good = encode({'fixture': 'first insert must roll back'})
bad = encode({'fixture': 'second insert raises SQL FAIL'})
keys = [cid_for(good), cid_for(bad)]
sql(database, "CREATE TRIGGER fail_second BEFORE INSERT ON blocks WHEN NEW.cid=X'" +
    keys[1].raw.hex() + "' BEGIN SELECT RAISE(FAIL,'injected second insert'); END")
with CaptureStore(EXE, database, writable=True) as store:
    try:
        store.import_blocks(list(zip(keys, [good, bad])))
    except InvalidObject as error:
        statement_error = str(error)
        assert 'injected second insert' in statement_error
    else:
        raise AssertionError('SQL failure was swallowed')
    assert sql(database, 'SELECT cid,data FROM blocks') == []
    sql(database, 'DROP TRIGGER fail_second')
    store.import_blocks(list(zip(keys, [good, bad])))
    assert store.read_blocks(keys) == list(zip(keys, [good, bad]))
    (OUT / 'resident-stdin.bin').write_bytes(store.raw_input)
    (OUT / 'resident-stdout.bin').write_bytes(store.raw_output)

